      <div class="color-box-value">
        ${r(e.exterior_inf_color_type,e.exterior_inf_color_code)?`<div class="color-swatch" style="background-color: ${r(e.exterior_inf_color_type,e.exterior_inf_color_code)}"></div>`:""}
        <span style="font-weight: 600; font-size: 13px;">${e.exterior_inf_color_type} &middot; ${e.exterior_inf_color_code}</span>
      </div>
